// AURA POSTs the tool's arguments as the JSON request body,
// so they arrive under `.body` -- not at the top level.
const args = $input.first().json.body ?? {};

// `summary` is what the model reads. Everything else stays available
// to AURA as structured data.
return [{
  json: {
    summary: `n8n is reachable. It received: ${JSON.stringify(args)}`,
    ok: true,
    received: args,
    at: new Date().toISOString()
  }
}];
